import functools
import pprint

from taf.gnb.oam.coam.cu.utilities.logger import log_error
from taf.gnb.oam.coam.cu.schemas.exceptions import SchemaInconsistent


class SchemaField:
    def __init__(self, name, not_null=False, optional=False, klass=None, many=False, nested_klass=None):
        """
        Single field of Schema ORM, based on this type the SchemaObject is transferring data to and from the object.

        :param str name: String name of the field in Schema
        :param bool not_null: If set to True, value of this parameter cannot be None or empty string.
        :param bool optional: If set to True, parameter does not have to be present in
                                the schema dict or in schema parameters, it will have default constructor value.
        :param Type[SchemaObject] klass: If set, the data that is identified by `name` will be deserialized using class = klass
        :param (SchemaObject|SchemaObjects) nested_klass: class to be used for deserialization of nested dict value,
                                                          e.g. for name="result"
                                                            {
                                                              "result": {
                                                                "MRBTS-1234/NRBTS-1234": nested_klass
                                                              }
                                                            }
        """
        self.name = name
        self.not_null = not_null
        self.optional = optional
        self.klass = klass
        self.many = many
        self.nested_klass = nested_klass


class SchemaObject:
    def __init__(self):
        """
        Simple ORM to convert data structures from APIs into Object and to serialize Objects.
        This is used to check the minimal contract, and to control data presentation.
        """
        self.__check_not_null()

    def __repr__(self):
        """For `print` and `pprint`"""
        return pprint.pformat(self.to_dict())

    def __eq__(self, other):
        """Returns true if both objects are equal"""
        if not isinstance(other, self.__class__):
            return False

        return self.to_dict() == other.to_dict()

    def __getitem__(self, key):
        """
        Allows getting the element of the object in a dict-like fashion
        for example: object["key"]
        """
        try:
            return self.__dict__[key]
        except KeyError:
            raise KeyError(f"'{key}' not found in instance attributes.")

    def __setitem__(self, key, value):
        """
        Allows setting adding the element to object in a dict-like fashion
        for example: object["key"] = value
        """
        self.__dict__[key] = value

    @classmethod
    def from_object_dict(cls, data):
        """
        Load data from structure into the object.
        If structure is of type list, returns list of objects.

        :param dict data: Data of given schema
        :return SchemaObject: Returns instance of subclass of SchemaObject.
        """
        if isinstance(data, list):
            return [cls._from_object_dict(element) for element in data]

        return cls._from_object_dict(data)

    def to_dict(self):
        """
        Serialize to dictionary structure.

        :return dict: Object as dict, with schema data parameters.
        """
        dict_data = {}

        try:
            for attribute_name in dir(self):

                object_type = type(self)
                model_field = getattr(object_type, attribute_name)
                if not isinstance(model_field, SchemaField) or attribute_name.startswith("_"):
                    continue

                attribute_value = getattr(self, attribute_name)
                parameter_name = attribute_name
                if not attribute_value and attribute_value not in (False, 0) and model_field.optional:
                    continue

                dict_data[parameter_name] = self.__deserialize(model_field, attribute_value)

        except AttributeError as e:
            raise SchemaInconsistent(f"Schema attributes that is being serialized is not consistent. Error on {e}")

        return dict_data

    @classmethod
    def _from_object_dict(cls, data):
        try:
            return cls(**cls.__map_data_to_object_attributes(data))

        except (KeyError, AttributeError, ValueError) as e:
            error_msg = f"\nSchema data is inconsistent or faulty.\nError on {e}"
            log_error(f"{error_msg}\n Data: {data}")

            raise SchemaInconsistent(error_msg)

    @classmethod
    def __map_data_to_object_attributes(cls, data):
        object_attributes = {}
        for attribute_name, attribute_field in cls.__get_schema_class_attributes():
            # noinspection PyBroadException
            try:
                extracted_value = cls.__rgetattr(data, attribute_field.name)
            except Exception:
                if attribute_field.optional:
                    continue
                raise

            object_attributes[attribute_name] = cls.__map_data(extracted_value, attribute_field)

        return object_attributes

    def __check_not_null(self):
        for attribute_name, attribute_field in self.__get_schema_class_attributes():
            if attribute_field.not_null:
                attribute_value = getattr(self, attribute_name)

                if attribute_value is None or attribute_value == "":
                    raise ValueError(f"{self.__class__.__name__} object attribute {attribute_name}"
                                     f" is not allowed to be empty, but its provided value is empty.")

    @classmethod
    def __get_schema_class_attributes(cls):
        for attribute_name in dir(cls):
            attribute_field = getattr(cls, attribute_name)

            if not isinstance(attribute_field, SchemaField):
                continue

            yield attribute_name, attribute_field

    @classmethod
    def __rgetattr(cls, obj, attr):
        def _getattr(obj, attr):
            if hasattr(obj, '__getitem__'):
                return obj.get(attr, None)

            return getattr(obj, attr, None)

        return functools.reduce(_getattr, [obj] + attr.split('.'))

    @classmethod
    def __map_data(cls, data, attribute_field):
        if data and attribute_field.klass:
            return cls.__map_data_to_object_or_object_list(data, attribute_field)

        elif data and attribute_field.nested_klass:
            return cls.__map_data_to_nested_object(data, attribute_field)

        else:
            return data

    @classmethod
    def __map_data_to_object_or_object_list(cls, data, attribute_field):
        if data and attribute_field.many:
            return list(map(attribute_field.klass.from_object_dict, data))

        return attribute_field.klass.from_object_dict(data)

    @classmethod
    def __map_data_to_nested_object(cls, data, attribute_field):
        return {item[0]: attribute_field.nested_klass.from_object_dict(item[1]) for item in data.items()}

    @staticmethod
    def __deserialize(model_field, attribute_value):
        if attribute_value and model_field.klass:
            return attribute_value.to_dict() if not model_field.many else [item.to_dict() for item in attribute_value]

        elif attribute_value and model_field.nested_klass:
            return {item[0]: item[1].to_dict() for item in attribute_value.items()}

        else:
            return attribute_value
